"""Settings loader for the nightly export job."""
import json
from pathlib import Path

DEFAULTS = {"retries": 3, "timeout_s": 20, "verbose": False}


def load_settings(path):
    """Read a JSON settings file and fill in defaults for missing keys."""
    settings = dict(DEFAULTS)
    p = Path(path)
    if p.exists():
        with p.open(encoding="utf-8") as fh:
            settings.update(json.load(fh))
    return settings


def validate(settings):
    if settings["retries"] < 0:
        raise ValueError("retries must be zero or more")
    if settings["timeout_s"] <= 0:
        raise ValueError("timeout_s must be positive")
    return settings


